import { useComfierPanelStore } from '@/comfier/panelStore'
import type { ManagerTab } from '@/workbench/extensions/manager/types/comfyManagerTypes'
export function useManagerDialog() {
  const panels = useComfierPanelStore()
  function hide() { panels.remove('comfier-extensions') }
  function show(initialTab?: ManagerTab, initialPackId?: string) {
    panels.managerTab = initialTab
    panels.managerPackId = initialPackId
    panels.select('comfier-extensions', panels.preferredSide)
  }
  return { show, hide }
}
